using Xunit;namespace CRM.ArchitectureTests;
public sealed class ReportingInsightArchitectureTests{static string Root(){var c=AppContext.BaseDirectory;while(!string.IsNullOrWhiteSpace(c)){if(File.Exists(Path.Combine(c,"CRM.sln")))return c;c=Directory.GetParent(c)?.FullName;}throw new DirectoryNotFoundException();}[Fact]public void Api_IsGetOnlyFoundation(){var p=File.ReadAllText(Path.Combine(Root(),"src","CRM.Api","Program.cs"));Assert.Contains("/api/crm/foundation/insights",p);Assert.DoesNotContain("MapPost(\"/api/crm/foundation/insights",p);Assert.DoesNotContain("MapPut(\"/api/crm/foundation/insights",p);Assert.DoesNotContain("MapDelete(\"/api/crm/foundation/insights",p);Assert.DoesNotContain("\"/api/crm/insights\"",p);}}